insert into public.photos (id, origine, chemin, largeur, hauteur, alt_fr, alt_en) values
  ('68b67169-8b12-5fc1-8b49-02ed36d43a69', 'site', '/images/hero-premiere-danse.jpg', 2400, 1600, 'Première danse des mariés dans la fumée lourde, sous les projecteurs', 'The couple''s first dance in low fog under stage lights'),
  ('c3ae3b2a-928b-5f87-acea-05a8ee81e4be', 'site', '/images/maison-mariage-ceremonie-arbres.jpg', 2400, 1600, 'Cérémonie laïque sous les arbres, avec pupitre et guitariste', 'Celebrant-led ceremony under the trees, with a lectern and a guitarist'),
  ('ad7c8d58-20b3-59c9-8ec9-413a1861d884', 'site', '/images/grange-guirlandes.jpg', 2400, 1600, 'Grange décorée de guirlandes lumineuses pour le dîner', 'Barn decorated with string lights for dinner'),
  ('442909e2-3670-5bed-bcf9-3f74f7a8723f', 'site', '/images/maison-mariage-danse-genou.jpg', 2400, 1800, 'Première danse des mariés sous des projections lumineuses bleues, entourés des invités', 'The couple''s first dance under blue light projections, surrounded by guests'),
  ('9f93c435-f0d0-5199-9b1f-3d33c6e54afc', 'site', '/images/maison-mariage-chateau-rose.jpg', 2400, 1800, 'Château illuminé en rose à la nuit tombée, braséro au premier plan', 'Château lit in pink at nightfall, with a fire pit in the foreground'),
  ('73ff7a2a-6d9e-5a6e-a922-660cb850c14d', 'site', '/images/maison-mariage-maries-micro.jpg', 2400, 1600, 'Mariés souriants qui prennent la parole au micro pendant la cérémonie', 'Smiling newlyweds speaking into the microphone during the ceremony'),
  ('03918149-a7a3-5665-8b8a-0f5a76e6a9cf', 'site', '/images/maison-mariage-salle-etoiles.jpg', 2400, 1596, 'Dîner de mariage dans une salle gothique, étoiles projetées au sol', 'Wedding dinner in a Gothic hall with stars projected on the floor'),
  ('f8250b4e-f008-50b9-aaf0-09cdc5e40cd8', 'site', '/images/couple-faisceaux.jpg', 2400, 1602, 'Mariés qui dansent entre deux faisceaux de lumière', 'Newlyweds dancing between two light beams'),
  ('72b3a730-1922-5887-81c7-d78e78e237f6', 'site', '/images/maison-mariage-chapiteau-fete.jpg', 1170, 1113, 'Soirée de mariage sous un chapiteau décoré de guirlandes lumineuses', 'Wedding party in a marquee decorated with fairy lights'),
  ('78707d33-b0e1-53b0-b243-e824d34f76ae', 'site', '/images/maison-mariage-charpente.jpg', 2400, 1600, 'Grande salle à charpente en bois mise en lumière pour un dîner de mariage', 'Timber-framed hall lit up for a wedding dinner'),
  ('453376b2-f490-5f5b-9189-a224d5e78ff7', 'site', '/images/maison-mariage-piste-verte.jpg', 1024, 1024, 'Piste de danse d''un mariage sous les faisceaux verts et la boule à facettes', 'Wedding dance floor under green beams and a mirror ball'),
  ('ea3820cf-13fb-5b55-989c-6b26921edf3e', 'site', '/images/chateau-cour.jpg', 2400, 1600, 'Cour de château mise en lumière pour une soirée de mariage', 'Château courtyard lit up for a wedding party'),
  ('0acad7f2-b535-5de3-8f6c-6b2b4514b612', 'site', '/images/maison-mariage-ceremonie-cour.jpg', 2400, 1800, 'Cérémonie laïque en plein air dans la cour d''un domaine', 'Outdoor celebrant-led ceremony in an estate courtyard'),
  ('7952a94b-27c9-5d4c-857d-cd01cef024ee', 'site', '/images/premiere-danse-rose.jpg', 2400, 1800, 'Première danse sous un motif lumineux rose', 'First dance under a pink light pattern'),
  ('09fc6360-a18f-5e61-ace2-d7fe9e6eebe6', 'site', '/images/maison-mariage-diner-rouge.jpg', 2400, 1800, 'Salle de réception éclairée en rouge et or pour un dîner de mariage', 'Reception room lit in red and gold for a wedding dinner'),
  ('69618ba3-239b-51f4-9202-a960bfe2697a', 'site', '/images/maison-mariage-lasers.jpg', 2400, 1597, 'Invités qui dansent sous des lasers roses et bleus', 'Guests dancing under pink and blue lasers'),
  ('0c3049bd-41b9-522c-9fe9-a5e77d0da61e', 'site', '/images/maison-mariage-chapiteau-nuit.jpg', 2400, 1600, 'Chapiteau transparent illuminé dans un jardin, de nuit', 'Illuminated clear marquee in a garden at night'),
  ('33626691-b95d-549c-b05c-9efc5b42e07f', 'site', '/images/maison-mariage-danse-gobos.jpg', 1214, 932, 'Mariés qui dansent sur une piste parsemée de taches de lumière', 'Newlyweds dancing on a floor dotted with spots of light'),
  ('8163d496-dae3-5b7b-b0ae-8ffb5e6e7371', 'site', '/images/maison-mariage-facade-projection.jpg', 2400, 1800, 'Façade de château habillée de projections lumineuses rouges', 'Château façade dressed with red light projections'),
  ('42b856b5-4c2c-5b31-8d7d-ec6877f205c0', 'site', '/images/chapiteau-diner.jpg', 2400, 1800, 'Dîner de mariage sous un chapiteau éclairé', 'Wedding dinner in an illuminated marquee'),
  ('cc401348-5925-5898-a936-ab8b4ddf30f0', 'site', '/images/maison-mariage-chapiteau-ovation.jpg', 2400, 1800, 'Invités debout qui acclament les mariés sous un chapiteau transparent', 'Guests on their feet cheering the couple in a clear marquee'),
  ('6d49267c-8e87-5d45-832d-30f993f3d769', 'site', '/images/maison-mariage-cour-gobos.jpg', 2400, 1600, 'Cour de château préparée pour la soirée : enceintes, colonnes lumineuses et piste éclairée', 'Château courtyard set up for the party: speakers, light columns and a lit dance floor'),
  ('88bcf888-7120-5234-8513-42d21a62158d', 'site', '/images/maison-mariage-diner-violet.jpg', 2400, 1800, 'Dîner de mariage sous un éclairage violet et des motifs lumineux', 'Wedding dinner under purple lighting and light patterns'),
  ('15324e70-e363-5b42-b220-ee1a55c8297b', 'site', '/images/maison-evenement-gala.jpg', 2400, 1600, 'Dîner de gala dans une salle de bal historique mise en lumière, avec écran', 'Gala dinner in a lit historic ballroom, with a screen'),
  ('d5df8ce8-e424-5e75-b475-0c00f7a0c661', 'site', '/images/maison-evenement-scene-dj.jpg', 2048, 1363, 'DJ sur une scène en structure, entouré du public', 'DJ on a truss stage, surrounded by the crowd'),
  ('e98831a0-c748-52a5-b83e-b6ea54da77a6', 'site', '/images/maison-evenement-bal.jpg', 1200, 800, 'Grande soirée dansante vue d''en haut, traversée de faisceaux lumineux', 'Large dance party seen from above, crossed by light beams'),
  ('6a51fe76-ff7f-5ef8-a9c1-ca5489c6f329', 'site', '/images/maison-evenement-lancement-auto.jpg', 1170, 1132, 'Lancement de voiture mis en lumière sous structures', 'Car launch lit up under truss structures'),
  ('80d6cde4-4d33-5479-8849-148c143fdd4f', 'site', '/images/maison-evenement-cabine-dj.jpg', 2048, 1536, 'Cabine DJ « Let''s Dance » encadrée de projecteurs', '“Let''s Dance” DJ booth framed by stage lights'),
  ('b1404f37-763c-5a88-9da8-7276228a2c2f', 'site', '/images/maison-evenement-soiree-lumiere.jpg', 1200, 800, 'Soirée d''entreprise sous une lumière jaune intense', 'Corporate party under intense yellow light'),
  ('14d339fa-8432-5d47-b294-62161c46725f', 'site', '/images/maison-evenement-seminaire.jpg', 1170, 1146, 'Scène et chaises installées pour un séminaire', 'Stage and seating set up for a seminar'),
  ('064b34fc-c25a-5e50-a7ff-50accc2936ce', 'site', '/images/maison-evenement-concert.jpg', 1200, 799, 'Public qui danse devant une régie DJ sur scène', 'Crowd dancing in front of a DJ booth on stage'),
  ('edc7c7b7-08c2-5a1a-a5fd-4251ca1802c4', 'site', '/images/maison-evenement-dj-vue-haut.jpg', 2048, 1363, 'DJ aux platines vu d''en haut, sous des faisceaux violets', 'DJ at the decks seen from above, under purple beams'),
  ('67683ce5-a81c-5736-abd6-48b1e95e38c0', 'site', '/images/maison-evenement-structure.jpg', 1170, 1145, 'Grande scène équipée de structures et de projecteurs', 'Large stage fitted with trusses and moving lights'),
  ('2968fb96-5e7a-5afe-8cd0-cc9152e02540', 'site', '/images/maison-evenement-faisceaux.jpg', 1170, 1140, 'Scène traversée de faisceaux lumineux bleus', 'Stage crossed by blue light beams'),
  ('6a7694fa-dd78-5b53-9aa1-729e15ff134d', 'site', '/images/presta-bal-fumee-nb.jpg', 900, 599, 'Ouverture de bal en noir et blanc, fumée au sol', 'First dance in black and white, with fog on the floor'),
  ('30eb5c92-a057-53ac-95a0-66fcc3e41c4c', 'site', '/images/vinyles.jpg', 2400, 1600, 'Caisse de vinyles du bar à vinyles', 'Crate of records from the vinyl bar'),
  ('1c245e09-d592-5bd4-9ed6-a256170422be', 'site', '/images/presta-vinyles-installation.jpg', 1200, 900, 'Bar à vinyles installé dans une salle de réception, caisses de disques et platines', 'Vinyl bar set up in a reception room, record crates and turntables'),
  ('566b01a4-ecdb-5f01-827b-d855311aaadb', 'site', '/images/presta-vinyles-veranda.jpg', 1200, 900, 'Bar à vinyles installé sous une verrière', 'Vinyl bar set up under a glass roof'),
  ('0342cc54-37a8-5b4b-9c64-b352a1b05b9f', 'site', '/images/presta-vinyles-platine.jpg', 2400, 1800, 'Vinyle posé sur la platine, prêt à être mixé', 'A record on the turntable, ready to be mixed'),
  ('33c3de61-d650-5b34-b0a7-da2c9397b463', 'site', '/images/telephone-livre-or.jpg', 1200, 1200, 'Téléphone vintage du livre d''or audio', 'Vintage telephone for the audio guestbook'),
  ('17779db2-026c-5ccd-90b4-b5c2658f00a8', 'site', '/images/presta-livre-or-cadre.jpg', 1200, 1800, 'Livre d''or audio : téléphone rétro et cadre d''instructions', 'Audio guestbook: retro phone and framed instructions'),
  ('3fab9a3a-d74b-599b-9ef2-9c15784525eb', 'site', '/images/presta-guirlandes-salle.jpg', 1600, 777, 'Salle en pierre illuminée par des guirlandes lumineuses au-dessus des tables', 'Stone hall lit by string lights above the tables'),
  ('c98c3516-ab5e-56e2-8c8c-bc853141f665', 'site', '/images/presta-guirlandes-grange.jpg', 1080, 1350, 'Mariés qui dansent sous un ciel de guirlandes dans une grange', 'Newlyweds dancing under a canopy of string lights in a barn'),
  ('9d17aee0-b8c3-5de2-832c-01150d9b286f', 'site', '/images/presta-guirlandes-diner.jpg', 896, 1280, 'Longues tablées sous des guirlandes lumineuses', 'Long banquet tables beneath string lights'),
  ('19df182d-5ce0-5d45-a78c-160308fa1873', 'site', '/images/presta-guirlandes-voilages.jpg', 1000, 1000, 'Guirlandes guinguette et voilages au-dessus d''un dîner aux chandelles', 'Festoon lights and drapes above a candlelit dinner'),
  ('bc79450a-88ea-589e-b0db-2b7db974ed8b', 'site', '/images/presta-mur-eau-colonnes.jpg', 1500, 2000, 'Mur d''eau encadré de végétation entre deux colonnes', 'Water wall framed by greenery between two columns'),
  ('94cd6f3e-5b85-5403-ab86-2daba0d8f617', 'site', '/images/presta-mur-vegetal-neon.jpg', 1920, 1760, 'Mur végétal agrémenté d''un néon personnalisé', 'Green wall with a personalised neon sign'),
  ('71604ce7-aa68-5612-bdcd-7e3a4b0b4a90', 'site', '/images/presta-mur-eau-nom.jpg', 2000, 1333, 'Mur d''eau personnalisé d''un nom lumineux', 'Water wall personalised with an illuminated name'),
  ('fc6b1d5e-36f3-5593-b64b-676c53378206', 'site', '/images/presta-mur-vegetal-escalier.jpg', 2048, 1536, 'Mur végétal mis en lumière dans un hall', 'Illuminated green wall in an entrance hall'),
  ('9727d033-d6b7-571c-9fe6-11fa9614b578', 'site', '/images/presta-mur-eau-vegetal.jpg', 2400, 2203, 'Mur d''eau personnalisé d''un logo, entouré d''un mur végétal', 'Water wall personalised with a logo, set in a green wall'),
  ('997d8416-5889-55e4-a567-92257b7ff59c', 'site', '/images/presta-mur-vegetal-salle.jpg', 2000, 1500, 'Mur végétal fleuri dans un espace de réception lumineux', 'Flowering green wall in a bright reception space'),
  ('9b795142-6ce9-5d06-a37d-b6bf3b9ee57d', 'site', '/images/presta-ceremonie-officiant.jpg', 2400, 1600, 'Officiant au micro pendant une cérémonie laïque en plein air', 'Celebrant speaking into a microphone at an outdoor ceremony'),
  ('19c2a557-5c9a-5570-8010-7298c5b332a1', 'site', '/images/presta-ceremonie-champ.jpg', 2400, 1600, 'Cérémonie laïque dans un pré, au micro devant les invités', 'Celebrant-led ceremony in a meadow, with a microphone, in front of the guests'),
  ('e147740a-ba8f-5d86-856d-ed6caa1e9290', 'site', '/images/presta-ceremonie-cour.jpg', 2400, 1800, 'Cérémonie laïque dans une cour ensoleillée, invités assis face aux musiciens', 'Celebrant-led ceremony in a sunny courtyard, guests seated facing the musicians'),
  ('6a627872-109d-5a05-aabe-edabeeb3e4ba', 'site', '/images/presta-sono-salle.jpg', 1080, 1350, 'Enceinte et contrôleur DJ installés dans une salle annexe', 'Speaker and DJ controller set up in a side room'),
  ('ba260d14-c4f8-503b-bd59-8425b09436a5', 'site', '/images/presta-sono-diner.jpg', 1024, 1536, 'Enceinte sur pied au bord d''une salle de dîner', 'Speaker on a stand at the edge of a dining room'),
  ('4ddf5f58-a78c-5836-82f0-8ef632878523', 'site', '/images/presta-chapiteau-nuit.jpg', 2400, 1600, 'Chapiteau éclairé de nuit, invités attablés pour le dîner', 'Marquee lit up at night, guests seated for dinner')
